INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1000, 1004, 'DI-101', 'MO — Yangi mavzu kirishi', 'Mashinaviy o''rganish', 3894, 'Linear regressiya — eng oddiy va eng asosiy ML algoritm. Maqsadi: kirish (X) va chiqish (y) o''rtasidagi chiziqli bog''liqlikni topish.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1000, 64, 61, 56, 62, 'O''rtacha sifatdagi dars — mavzu qamrab olindi, lekin o''quvchilar reaktsiyasiga ko''p e''tibor berilmadi.', '["Vizual yoki yozma misollar kontsentratsiyaga yordam berdi.","Misollar amaliy va o''quvchilarga tushunarli."]', '["O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak.","Murakkab atamalar uchun qisqacha takror berib turish foydali.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi."]', '["Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish.","Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi.","Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin."]', '2026-04-17 12:38:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1001, 1004, 'DI-101', 'MO — Test va o''zlashtirish', 'Mashinaviy o''rganish', 3314, 'Linear regressiya — eng oddiy va eng asosiy ML algoritm. Maqsadi: kirish (X) va chiqish (y) o''rtasidagi chiziqli bog''liqlikni topish.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1001, 88, 95, 80, 89, 'Mazmun va shaklning yaxshi muvozanati. Misollar mavzuni qo''llab-quvvatlaydi.', '["Misollar amaliy va o''quvchilarga tushunarli.","O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan.","O''qituvchi savollarga aniq javob berdi."]', '["Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak.","Murakkab atamalar uchun qisqacha takror berib turish foydali.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi."]', '["Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi.","Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi."]', '2026-04-23 09:39:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1002, 1004, 'DI-101', 'MO — Yechimlar muhokamasi', 'Mashinaviy o''rganish', 2652, 'Linear regressiya — eng oddiy va eng asosiy ML algoritm. Maqsadi: kirish (X) va chiqish (y) o''rtasidagi chiziqli bog''liqlikni topish.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1002, 64, 58, 56, 65, 'Asosiy mavzu yetkazildi, lekin tushuntirishda ba''zi joylar tezroq o''tib ketdi.', '["Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi.","O''qituvchi savollarga aniq javob berdi.","Ovoz baland va aniq, jaranglashi yaxshi."]', '["Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish."]', '["Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish.","Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi."]', '2026-04-26 11:09:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1003, 1004, 'DI-101', 'MO — Takrorlash va xulosa', 'Mashinaviy o''rganish', 2640, 'Linear regressiya — eng oddiy va eng asosiy ML algoritm. Maqsadi: kirish (X) va chiqish (y) o''rtasidagi chiziqli bog''liqlikni topish.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1003, 88, 90, 81, 82, 'Pedagogik jihatdan kuchli dars. Kichik takomillashtirishlar bilan a''lo bo''lishi mumkin.', '["Misollar amaliy va o''quvchilarga tushunarli.","Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi.","Real hayotdagi misollar yordamida nazariya mustahkamlandi."]', '["Murakkab atamalar uchun qisqacha takror berib turish foydali.","Yozma misollarni daftar yoki taxta orqali ko''rsatish."]', '["Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin.","Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi.","Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish."]', '2026-03-02 08:16:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1004, 1004, 'DI-101', 'MO — Amaliy mashq', 'Mashinaviy o''rganish', 2560, 'Linear regressiya — eng oddiy va eng asosiy ML algoritm. Maqsadi: kirish (X) va chiqish (y) o''rtasidagi chiziqli bog''liqlikni topish.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1004, 70, 67, 65, 72, 'Dars umumiy ma''noda yaxshi olib borildi, lekin amaliy qism va o''quvchilarni jalb qilish kuchaytirilishi kerak.', '["Real hayotdagi misollar yordamida nazariya mustahkamlandi.","Vizual yoki yozma misollar kontsentratsiyaga yordam berdi.","Mavzu aniq va izchil yoritildi."]', '["Murakkab atamalar uchun qisqacha takror berib turish foydali.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish."]', '["Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi.","Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi.","Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi."]', '2026-04-23 03:40:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1005, 1007, 'DI-101', 'DM — Loyiha taqdimoti', 'Diskret matematika', 2279, 'Bugungi mavzu — to''plamlar va ulardagi amallar. To''plam — bu aniq belgilangan obyektlar yig''indisi. A = {1, 2, 3} kabi yoziladi. Element to''plamga tegishli yoki tegishli emas.
