INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1008, 82, 78, 85, 78, 'Pedagogik jihatdan kuchli dars. Kichik takomillashtirishlar bilan a''lo bo''lishi mumkin.', '["Mavzu aniq va izchil yoritildi.","Real hayotdagi misollar yordamida nazariya mustahkamlandi.","Vizual yoki yozma misollar kontsentratsiyaga yordam berdi."]', '["Yozma misollarni daftar yoki taxta orqali ko''rsatish.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish.","O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak."]', '["Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi.","Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin.","Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish."]', '2026-04-17 05:28:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1009, 1008, 'DI-102', 'IN — Test va o''zlashtirish', 'Iqtisodiyot nazariyasi', 1400, 'Talab va taklif qonuni — bozor iqtisodiyotining asosi. Talab — xaridorlar ma''lum narxda sotib olishga tayyor bo''lgan miqdor. Taklif — sotuvchilar shu narxda sotishga tayyor miqdor.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1009, 76, 69, 78, 84, 'Dars umumiy ma''noda yaxshi olib borildi, lekin amaliy qism va o''quvchilarni jalb qilish kuchaytirilishi kerak.', '["O''qituvchi savollarga aniq javob berdi.","Misollar amaliy va o''quvchilarga tushunarli."]', '["Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak.","Yozma misollarni daftar yoki taxta orqali ko''rsatish."]', '["Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi.","Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin.","Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi."]', '2026-04-12 09:52:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1010, 1008, 'DI-102', 'IN — Yangi mavzu kirishi', 'Iqtisodiyot nazariyasi', 3933, 'Talab va taklif qonuni — bozor iqtisodiyotining asosi. Talab — xaridorlar ma''lum narxda sotib olishga tayyor bo''lgan miqdor. Taklif — sotuvchilar shu narxda sotishga tayyor miqdor.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1010, 79, 75, 75, 76, 'Asosiy mavzu yetkazildi, lekin tushuntirishda ba''zi joylar tezroq o''tib ketdi.', '["Real hayotdagi misollar yordamida nazariya mustahkamlandi.","Misollar amaliy va o''quvchilarga tushunarli.","Mavzu aniq va izchil yoritildi."]', '["Yozma misollarni daftar yoki taxta orqali ko''rsatish.","Murakkab atamalar uchun qisqacha takror berib turish foydali.","Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi."]', '["Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi.","Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi."]', '2026-03-15 12:48:00');
