INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1016, 1001, 'DI-102', 'AMT — Loyiha taqdimoti', 'Algoritmlar va ma''lumotlar tuzilmalari', 3675, 'Stack va Queue — eng asosiy ma''lumotlar tuzilmalari. Stack LIFO printsipida ishlaydi: oxirgi qo''yilgan element birinchi olinadi. Aslida bu plitalar uyumiga o''xshaydi.
