INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1017, 1001, 'DI-102', 'AMT — Asosiy tushunchalar', 'Algoritmlar va ma''lumotlar tuzilmalari', 3032, 'Bugungi mavzuimiz — Big O notatsiyasi. Algoritmni baholash uchun biz uning vaqt va xotira murakkabligini hisoblashimiz kerak. Big O — bu eng yomon holat uchun o''sish darajasini ifodalovchi notatsiya.
