INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1025, 1009, 'DI-201', 'LB — Test va o''zlashtirish', 'Loyihalarni boshqarish', 2839, 'Agile metodologiyasi — bu loyihalarni iterativ tarzda boshqarish yondashuvi. Asoschi 2001-yilda 17 dasturchi yozgan Agile Manifesto.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1025, 90, 97, 94, 93, 'Mazmun va shaklning yaxshi muvozanati. Misollar mavzuni qo''llab-quvvatlaydi.', '["Mavzu aniq va izchil yoritildi.","O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan.","Vizual yoki yozma misollar kontsentratsiyaga yordam berdi."]', '["Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi."]', '["Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi.","Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi."]', '2026-04-27 06:08:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1026, 1009, 'DI-201', 'LB — Asosiy tushunchalar', 'Loyihalarni boshqarish', 2464, 'Agile metodologiyasi — bu loyihalarni iterativ tarzda boshqarish yondashuvi. Asoschi 2001-yilda 17 dasturchi yozgan Agile Manifesto.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1026, 61, 62, 66, 55, 'O''rtacha sifatdagi dars — mavzu qamrab olindi, lekin o''quvchilar reaktsiyasiga ko''p e''tibor berilmadi.', '["Misollar amaliy va o''quvchilarga tushunarli.","Mavzu aniq va izchil yoritildi."]', '["Yozma misollarni daftar yoki taxta orqali ko''rsatish.","O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak."]', '["Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi.","Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi."]', '2026-04-06 11:57:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1027, 1009, 'DI-201', 'LB — Test va o''zlashtirish', 'Loyihalarni boshqarish', 1301, 'Agile metodologiyasi — bu loyihalarni iterativ tarzda boshqarish yondashuvi. Asoschi 2001-yilda 17 dasturchi yozgan Agile Manifesto.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1027, 74, 72, 76, 69, 'Asosiy mavzu yetkazildi, lekin tushuntirishda ba''zi joylar tezroq o''tib ketdi.', '["O''qituvchi savollarga aniq javob berdi.","Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi."]', '["Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi.","Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","Yozma misollarni daftar yoki taxta orqali ko''rsatish."]', '["Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi.","Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi.","Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi."]', '2026-04-24 03:59:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1028, 1009, 'DI-201', 'LB — Test va o''zlashtirish', 'Loyihalarni boshqarish', 4064, 'Agile metodologiyasi — bu loyihalarni iterativ tarzda boshqarish yondashuvi. Asoschi 2001-yilda 17 dasturchi yozgan Agile Manifesto.
