INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1032, 84, 89, 85, 86, 'Dars yaxshi tashkil etilgan, mavzu chuqur va aniq yoritilgan. O''quvchilar bilan muloqot mustahkam.', '["Mavzu aniq va izchil yoritildi.","Misollar amaliy va o''quvchilarga tushunarli."]', '["Yozma misollarni daftar yoki taxta orqali ko''rsatish.","Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak."]', '["Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi.","Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish.","Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi."]', '2026-04-27 04:07:00');
