INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1041, 1001, 'DI-301', 'AMT — Yangi mavzu kirishi', 'Algoritmlar va ma''lumotlar tuzilmalari', 2974, 'Bugungi mavzuimiz — Big O notatsiyasi. Algoritmni baholash uchun biz uning vaqt va xotira murakkabligini hisoblashimiz kerak. Big O — bu eng yomon holat uchun o''sish darajasini ifodalovchi notatsiya.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1041, 77, 75, 74, 79, 'Dars umumiy ma''noda yaxshi olib borildi, lekin amaliy qism va o''quvchilarni jalb qilish kuchaytirilishi kerak.', '["Real hayotdagi misollar yordamida nazariya mustahkamlandi.","Ovoz baland va aniq, jaranglashi yaxshi.","O''qituvchi savollarga aniq javob berdi."]', '["Yozma misollarni daftar yoki taxta orqali ko''rsatish.","O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak.","Murakkab atamalar uchun qisqacha takror berib turish foydali."]', '["Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin.","Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi."]', '2026-02-28 10:58:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1042, 1001, 'DI-301', 'AMT — Loyiha taqdimoti', 'Algoritmlar va ma''lumotlar tuzilmalari', 1700, 'Bugungi mavzuimiz — Big O notatsiyasi. Algoritmni baholash uchun biz uning vaqt va xotira murakkabligini hisoblashimiz kerak. Big O — bu eng yomon holat uchun o''sish darajasini ifodalovchi notatsiya.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1042, 81, 79, 73, 85, 'Dars yaxshi tashkil etilgan, mavzu chuqur va aniq yoritilgan. O''quvchilar bilan muloqot mustahkam.', '["O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan.","Ovoz baland va aniq, jaranglashi yaxshi.","O''qituvchi savollarga aniq javob berdi."]', '["Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak.","Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi."]', '["Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi.","Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi."]', '2026-04-02 08:33:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1043, 1001, 'DI-301', 'AMT — Yechimlar muhokamasi', 'Algoritmlar va ma''lumotlar tuzilmalari', 2457, 'Bugungi mavzuimiz — Big O notatsiyasi. Algoritmni baholash uchun biz uning vaqt va xotira murakkabligini hisoblashimiz kerak. Big O — bu eng yomon holat uchun o''sish darajasini ifodalovchi notatsiya.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1043, 77, 70, 67, 84, 'Asosiy mavzu yetkazildi, lekin tushuntirishda ba''zi joylar tezroq o''tib ketdi.', '["Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi.","O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan.","Misollar amaliy va o''quvchilarga tushunarli."]', '["Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi.","Murakkab atamalar uchun qisqacha takror berib turish foydali."]', '["Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi.","Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin."]', '2026-04-25 03:10:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1044, 1001, 'DI-301', 'AMT — Yechimlar muhokamasi', 'Algoritmlar va ma''lumotlar tuzilmalari', 2887, 'Bugungi mavzuimiz — Big O notatsiyasi. Algoritmni baholash uchun biz uning vaqt va xotira murakkabligini hisoblashimiz kerak. Big O — bu eng yomon holat uchun o''sish darajasini ifodalovchi notatsiya.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1044, 86, 91, 88, 80, 'Mazmun va shaklning yaxshi muvozanati. Misollar mavzuni qo''llab-quvvatlaydi.', '["Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi.","Ovoz baland va aniq, jaranglashi yaxshi."]', '["Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish.","Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak."]', '["Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi.","Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin."]', '2026-04-14 10:21:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1045, 1001, 'DI-301', 'AMT — Yechimlar muhokamasi', 'Algoritmlar va ma''lumotlar tuzilmalari', 3817, 'Stack va Queue — eng asosiy ma''lumotlar tuzilmalari. Stack LIFO printsipida ishlaydi: oxirgi qo''yilgan element birinchi olinadi. Aslida bu plitalar uyumiga o''xshaydi.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1045, 64, 61, 59, 66, 'O''rtacha sifatdagi dars — mavzu qamrab olindi, lekin o''quvchilar reaktsiyasiga ko''p e''tibor berilmadi.', '["O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan.","Ovoz baland va aniq, jaranglashi yaxshi."]', '["O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi."]', '["Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin.","Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi.","Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi."]', '2026-03-10 09:34:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1046, 1001, 'DI-301', 'AMT — Misollar va tahlil', 'Algoritmlar va ma''lumotlar tuzilmalari', 3289, 'Bugungi mavzuimiz — Big O notatsiyasi. Algoritmni baholash uchun biz uning vaqt va xotira murakkabligini hisoblashimiz kerak. Big O — bu eng yomon holat uchun o''sish darajasini ifodalovchi notatsiya.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1046, 85, 93, 92, 89, 'Mazmun va shaklning yaxshi muvozanati. Misollar mavzuni qo''llab-quvvatlaydi.', '["O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan.","Mavzu aniq va izchil yoritildi."]', '["Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak.","Yozma misollarni daftar yoki taxta orqali ko''rsatish.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish."]', '["Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi.","Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish."]', '2026-03-15 08:23:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1047, 1002, 'DI-301', 'VD — Amaliy mashq', 'Veb dasturlash', 2959, 'React komponentlari haqida gaplashamiz. Komponent — bu UI ning qayta ishlatiladigan qismi. Function komponent eng zamonaviy yondashuv hisoblanadi.
