INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1048, 1002, 'DI-301', 'VD — Takrorlash va xulosa', 'Veb dasturlash', 1284, 'Bugun biz HTTP protokolining asoslarini ko''rib chiqamiz. HTTP — bu mijoz va server o''rtasidagi muloqot tili. Brauzer so''rov yuboradi, server javob beradi.
