INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1058, 1001, 'DI-401', 'MB — Asosiy tushunchalar', 'Ma''lumotlar bazalari', 2961, 'Bugun normalizatsiya haqida gaplashamiz. Normalizatsiya — bu jadvallarni qayta tashkil etish, ortiqcha ma''lumotni kamaytirish va yaxlitlikni saqlash usulidir.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1058, 82, 77, 90, 87, 'Pedagogik jihatdan kuchli dars. Kichik takomillashtirishlar bilan a''lo bo''lishi mumkin.', '["Misollar amaliy va o''quvchilarga tushunarli.","Vizual yoki yozma misollar kontsentratsiyaga yordam berdi.","Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi."]', '["Yozma misollarni daftar yoki taxta orqali ko''rsatish.","Murakkab atamalar uchun qisqacha takror berib turish foydali.","O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak."]', '["Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi.","Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi."]', '2026-03-28 11:56:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1059, 1001, 'DI-401', 'MB — Test va o''zlashtirish', 'Ma''lumotlar bazalari', 4339, 'Bugun normalizatsiya haqida gaplashamiz. Normalizatsiya — bu jadvallarni qayta tashkil etish, ortiqcha ma''lumotni kamaytirish va yaxlitlikni saqlash usulidir.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1059, 89, 86, 88, 94, 'Dars yaxshi tashkil etilgan, mavzu chuqur va aniq yoritilgan. O''quvchilar bilan muloqot mustahkam.', '["Misollar amaliy va o''quvchilarga tushunarli.","Ovoz baland va aniq, jaranglashi yaxshi.","Real hayotdagi misollar yordamida nazariya mustahkamlandi."]', '["Yozma misollarni daftar yoki taxta orqali ko''rsatish.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish.","Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak."]', '["Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi.","Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi."]', '2026-04-08 07:50:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1060, 1001, 'DI-401', 'MB — Amaliy mashq', 'Ma''lumotlar bazalari', 4119, 'Bugun normalizatsiya haqida gaplashamiz. Normalizatsiya — bu jadvallarni qayta tashkil etish, ortiqcha ma''lumotni kamaytirish va yaxlitlikni saqlash usulidir.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1060, 62, 63, 50, 65, 'O''rtacha sifatdagi dars — mavzu qamrab olindi, lekin o''quvchilar reaktsiyasiga ko''p e''tibor berilmadi.', '["Misollar amaliy va o''quvchilarga tushunarli.","Vizual yoki yozma misollar kontsentratsiyaga yordam berdi."]', '["Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish.","Yozma misollarni daftar yoki taxta orqali ko''rsatish."]', '["Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi.","Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi."]', '2026-03-12 06:18:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1061, 1001, 'DI-401', 'MB — Yangi mavzu kirishi', 'Ma''lumotlar bazalari', 3609, 'Bugun normalizatsiya haqida gaplashamiz. Normalizatsiya — bu jadvallarni qayta tashkil etish, ortiqcha ma''lumotni kamaytirish va yaxlitlikni saqlash usulidir.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1061, 61, 63, 51, 58, 'Dars umumiy ma''noda yaxshi olib borildi, lekin amaliy qism va o''quvchilarni jalb qilish kuchaytirilishi kerak.', '["O''qituvchi savollarga aniq javob berdi.","Misollar amaliy va o''quvchilarga tushunarli.","Ovoz baland va aniq, jaranglashi yaxshi."]', '["O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi."]', '["Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi.","Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi."]', '2026-03-10 09:55:00');
