INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1074, 1008, 'SI-101', 'IN — Misollar va tahlil', 'Iqtisodiyot nazariyasi', 1846, 'Talab va taklif qonuni — bozor iqtisodiyotining asosi. Talab — xaridorlar ma''lum narxda sotib olishga tayyor bo''lgan miqdor. Taklif — sotuvchilar shu narxda sotishga tayyor miqdor.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1074, 87, 95, 89, 87, 'Mazmun va shaklning yaxshi muvozanati. Misollar mavzuni qo''llab-quvvatlaydi.', '["Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi.","O''qituvchi savollarga aniq javob berdi."]', '["Yozma misollarni daftar yoki taxta orqali ko''rsatish.","Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak."]', '["Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi.","Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi.","Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi."]', '2026-04-16 08:19:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1075, 1002, 'SI-201', 'VD — Misollar va tahlil', 'Veb dasturlash', 3021, 'React komponentlari haqida gaplashamiz. Komponent — bu UI ning qayta ishlatiladigan qismi. Function komponent eng zamonaviy yondashuv hisoblanadi.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1075, 81, 85, 89, 89, 'Mazmun va shaklning yaxshi muvozanati. Misollar mavzuni qo''llab-quvvatlaydi.', '["Misollar amaliy va o''quvchilarga tushunarli.","Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi.","O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan."]', '["Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak.","Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish."]', '["Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi.","Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi.","Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi."]', '2026-04-11 12:03:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1076, 1002, 'SI-201', 'VD — Yechimlar muhokamasi', 'Veb dasturlash', 4073, 'Bugun biz HTTP protokolining asoslarini ko''rib chiqamiz. HTTP — bu mijoz va server o''rtasidagi muloqot tili. Brauzer so''rov yuboradi, server javob beradi.
