INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1091, 1004, 'MA-101', 'MO — Amaliy mashq', 'Mashinaviy o''rganish', 1728, 'Linear regressiya — eng oddiy va eng asosiy ML algoritm. Maqsadi: kirish (X) va chiqish (y) o''rtasidagi chiziqli bog''liqlikni topish.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1091, 68, 67, 64, 65, 'Dars umumiy ma''noda yaxshi olib borildi, lekin amaliy qism va o''quvchilarni jalb qilish kuchaytirilishi kerak.', '["Vizual yoki yozma misollar kontsentratsiyaga yordam berdi.","O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan."]', '["Murakkab atamalar uchun qisqacha takror berib turish foydali.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish."]', '["Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish.","Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi.","Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi."]', '2026-03-09 03:14:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1092, 1004, 'MA-101', 'MO — Asosiy tushunchalar', 'Mashinaviy o''rganish', 3315, 'Linear regressiya — eng oddiy va eng asosiy ML algoritm. Maqsadi: kirish (X) va chiqish (y) o''rtasidagi chiziqli bog''liqlikni topish.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1092, 84, 76, 88, 84, 'Dars yaxshi tashkil etilgan, mavzu chuqur va aniq yoritilgan. O''quvchilar bilan muloqot mustahkam.', '["O''qituvchi savollarga aniq javob berdi.","Ovoz baland va aniq, jaranglashi yaxshi.","Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi."]', '["Yozma misollarni daftar yoki taxta orqali ko''rsatish.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish.","Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi."]', '["Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi.","Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi."]', '2026-03-14 10:34:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1093, 1004, 'MA-101', 'MO — Misollar va tahlil', 'Mashinaviy o''rganish', 4409, 'Linear regressiya — eng oddiy va eng asosiy ML algoritm. Maqsadi: kirish (X) va chiqish (y) o''rtasidagi chiziqli bog''liqlikni topish.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1093, 79, 76, 80, 78, 'Dars umumiy ma''noda yaxshi olib borildi, lekin amaliy qism va o''quvchilarni jalb qilish kuchaytirilishi kerak.', '["O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan.","Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi."]', '["Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","Murakkab atamalar uchun qisqacha takror berib turish foydali."]', '["Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi.","Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin."]', '2026-04-02 11:00:00');
