INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1094, 82, 76, 90, 78, 'Mazmun va shaklning yaxshi muvozanati. Misollar mavzuni qo''llab-quvvatlaydi.', '["Vizual yoki yozma misollar kontsentratsiyaga yordam berdi.","O''qituvchi savollarga aniq javob berdi."]', '["O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak.","Murakkab atamalar uchun qisqacha takror berib turish foydali.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi."]', '["Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi.","Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi.","Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish."]', '2026-04-27 03:27:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1095, 1004, 'MA-201', 'SIA — Loyiha taqdimoti', 'Sun''iy intellekt asoslari', 2866, 'Sun''iy intellekt nima va nima emas? Bugun biz aniq belgilab olamiz. AI — bu kompyuter sistemalari odam aql talab qiladigan vazifalarni bajarishi. Lekin bu film kabi sezuvchi mavjudot emas.
