INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1107, 67, 60, 64, 62, 'Dars umumiy ma''noda yaxshi olib borildi, lekin amaliy qism va o''quvchilarni jalb qilish kuchaytirilishi kerak.', '["Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi.","Ovoz baland va aniq, jaranglashi yaxshi."]', '["Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish.","O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak.","Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak."]', '["Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish.","Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi.","Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi."]', '2026-03-23 10:44:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1108, 1006, 'RI-101', 'OT — Test va o''zlashtirish', 'Operatsion tizimlar', 4214, 'Operatsion tizim — bu kompyuter resurslarini boshqaruvchi va dasturlarga muhit yaratuvchi dastur. Asosiy funksiyalari: jarayonlarni boshqarish, xotira boshqaruvi, fayl tizimi, qurilmalar bilan ishlash.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1108, 85, 78, 76, 84, 'Pedagogik jihatdan kuchli dars. Kichik takomillashtirishlar bilan a''lo bo''lishi mumkin.', '["Real hayotdagi misollar yordamida nazariya mustahkamlandi.","O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan.","Ovoz baland va aniq, jaranglashi yaxshi."]', '["Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish."]', '["Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi.","Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi."]', '2026-03-30 10:53:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1109, 1006, 'RI-101', 'OT — Misollar va tahlil', 'Operatsion tizimlar', 1006, 'Operatsion tizim — bu kompyuter resurslarini boshqaruvchi va dasturlarga muhit yaratuvchi dastur. Asosiy funksiyalari: jarayonlarni boshqarish, xotira boshqaruvi, fayl tizimi, qurilmalar bilan ishlash.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1109, 62, 58, 50, 61, 'O''rtacha sifatdagi dars — mavzu qamrab olindi, lekin o''quvchilar reaktsiyasiga ko''p e''tibor berilmadi.', '["O''qituvchi savollarga aniq javob berdi.","Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi.","Misollar amaliy va o''quvchilarga tushunarli."]', '["Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak.","O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak."]', '["Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish.","Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi.","Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi."]', '2026-04-25 06:59:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1110, 1004, 'RI-101', 'SIA — Misollar va tahlil', 'Sun''iy intellekt asoslari', 2836, 'Sun''iy intellekt nima va nima emas? Bugun biz aniq belgilab olamiz. AI — bu kompyuter sistemalari odam aql talab qiladigan vazifalarni bajarishi. Lekin bu film kabi sezuvchi mavjudot emas.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1110, 76, 81, 78, 86, 'Asosiy mavzu yetkazildi, lekin tushuntirishda ba''zi joylar tezroq o''tib ketdi.', '["O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan.","Mavzu aniq va izchil yoritildi."]', '["Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish."]', '["Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi.","Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi.","Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi."]', '2026-02-28 04:10:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1111, 1004, 'RI-101', 'SIA — Loyiha taqdimoti', 'Sun''iy intellekt asoslari', 2847, 'Sun''iy intellekt nima va nima emas? Bugun biz aniq belgilab olamiz. AI — bu kompyuter sistemalari odam aql talab qiladigan vazifalarni bajarishi. Lekin bu film kabi sezuvchi mavjudot emas.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1111, 86, 87, 94, 89, 'Pedagogik jihatdan kuchli dars. Kichik takomillashtirishlar bilan a''lo bo''lishi mumkin.', '["O''qituvchi savollarga aniq javob berdi.","O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan.","Misollar amaliy va o''quvchilarga tushunarli."]', '["Yozma misollarni daftar yoki taxta orqali ko''rsatish.","Murakkab atamalar uchun qisqacha takror berib turish foydali."]', '["Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi.","Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin."]', '2026-04-21 11:51:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1112, 1004, 'RI-101', 'SIA — Misollar va tahlil', 'Sun''iy intellekt asoslari', 2636, 'Sun''iy intellekt nima va nima emas? Bugun biz aniq belgilab olamiz. AI — bu kompyuter sistemalari odam aql talab qiladigan vazifalarni bajarishi. Lekin bu film kabi sezuvchi mavjudot emas.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1112, 82, 77, 72, 87, 'Dars yaxshi tashkil etilgan, mavzu chuqur va aniq yoritilgan. O''quvchilar bilan muloqot mustahkam.', '["Mavzu aniq va izchil yoritildi.","Ovoz baland va aniq, jaranglashi yaxshi.","Real hayotdagi misollar yordamida nazariya mustahkamlandi."]', '["Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish."]', '["Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi.","Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin."]', '2026-04-12 06:30:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1113, 1004, 'RI-101', 'SIA — Yechimlar muhokamasi', 'Sun''iy intellekt asoslari', 1334, 'Sun''iy intellekt nima va nima emas? Bugun biz aniq belgilab olamiz. AI — bu kompyuter sistemalari odam aql talab qiladigan vazifalarni bajarishi. Lekin bu film kabi sezuvchi mavjudot emas.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1113, 84, 80, 76, 91, 'Mazmun va shaklning yaxshi muvozanati. Misollar mavzuni qo''llab-quvvatlaydi.', '["Mavzu aniq va izchil yoritildi.","Vizual yoki yozma misollar kontsentratsiyaga yordam berdi."]', '["Murakkab atamalar uchun qisqacha takror berib turish foydali.","Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi."]', '["Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi.","Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi."]', '2026-03-17 09:21:00');
