INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1124, 69, 66, 57, 63, 'Asosiy mavzu yetkazildi, lekin tushuntirishda ba''zi joylar tezroq o''tib ketdi.', '["Mavzu aniq va izchil yoritildi.","Misollar amaliy va o''quvchilarga tushunarli."]', '["O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak.","Murakkab atamalar uchun qisqacha takror berib turish foydali.","Yozma misollarni daftar yoki taxta orqali ko''rsatish."]', '["Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi.","Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi."]', '2026-04-16 08:00:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1125, 1000, 'SI-201', 'DA — Asosiy tushunchalar', 'Dasturlash asoslari', 1116, 'Bugun shartli operatorlar mavzusiga to''xtalamiz. Dastur har doim chiziqli bajarilmaydi — ba''zan biz uning yo''nalishini boshqarishimiz kerak. Buning uchun if konstruksiyasidan foydalanamiz.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1125, 78, 72, 84, 83, 'Asosiy mavzu yetkazildi, lekin tushuntirishda ba''zi joylar tezroq o''tib ketdi.', '["Vizual yoki yozma misollar kontsentratsiyaga yordam berdi.","Misollar amaliy va o''quvchilarga tushunarli."]', '["Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish.","Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak."]', '["Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi.","Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi."]', '2026-03-20 09:26:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1126, 1000, 'SI-201', 'DA — Yechimlar muhokamasi', 'Dasturlash asoslari', 3042, 'Funksiyalar — bu kodni qayta ishlatish uchun asosiy vosita. def kalit so''zi bilan funksiyani aniqlaymiz. Argumentlar qavslar ichida, return orqali qiymat qaytariladi.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1126, 69, 69, 69, 64, 'O''rtacha sifatdagi dars — mavzu qamrab olindi, lekin o''quvchilar reaktsiyasiga ko''p e''tibor berilmadi.', '["O''qituvchi savollarga aniq javob berdi.","Vizual yoki yozma misollar kontsentratsiyaga yordam berdi."]', '["Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi."]', '["Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin.","Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi.","Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi."]', '2026-04-24 07:36:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1127, 1000, 'SI-201', 'DA — Yangi mavzu kirishi', 'Dasturlash asoslari', 3226, 'Bugun shartli operatorlar mavzusiga to''xtalamiz. Dastur har doim chiziqli bajarilmaydi — ba''zan biz uning yo''nalishini boshqarishimiz kerak. Buning uchun if konstruksiyasidan foydalanamiz.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1127, 90, 82, 86, 98, 'Mazmun va shaklning yaxshi muvozanati. Misollar mavzuni qo''llab-quvvatlaydi.', '["O''qituvchi savollarga aniq javob berdi.","Ovoz baland va aniq, jaranglashi yaxshi.","Vizual yoki yozma misollar kontsentratsiyaga yordam berdi."]', '["O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi.","Yozma misollarni daftar yoki taxta orqali ko''rsatish."]', '["Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi.","Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi."]', '2026-03-27 03:28:00');
