INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1140, 80, 74, 71, 79, 'Pedagogik jihatdan kuchli dars. Kichik takomillashtirishlar bilan a''lo bo''lishi mumkin.', '["O''qituvchi savollarga aniq javob berdi.","Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi."]', '["Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish.","Murakkab atamalar uchun qisqacha takror berib turish foydali."]', '["Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi.","Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi.","Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi."]', '2026-04-19 06:19:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1141, 1001, 'MA-201', 'AMT — Loyiha taqdimoti', 'Algoritmlar va ma''lumotlar tuzilmalari', 3996, 'Bugungi mavzuimiz — Big O notatsiyasi. Algoritmni baholash uchun biz uning vaqt va xotira murakkabligini hisoblashimiz kerak. Big O — bu eng yomon holat uchun o''sish darajasini ifodalovchi notatsiya.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1141, 84, 91, 82, 88, 'Mazmun va shaklning yaxshi muvozanati. Misollar mavzuni qo''llab-quvvatlaydi.', '["Real hayotdagi misollar yordamida nazariya mustahkamlandi.","O''qituvchi savollarga aniq javob berdi."]', '["Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish."]', '["Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi.","Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish.","Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi."]', '2026-03-03 05:32:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1142, 1001, 'MA-201', 'AMT — Takrorlash va xulosa', 'Algoritmlar va ma''lumotlar tuzilmalari', 3724, 'Stack va Queue — eng asosiy ma''lumotlar tuzilmalari. Stack LIFO printsipida ishlaydi: oxirgi qo''yilgan element birinchi olinadi. Aslida bu plitalar uyumiga o''xshaydi.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1142, 68, 70, 67, 73, 'Dars umumiy ma''noda yaxshi olib borildi, lekin amaliy qism va o''quvchilarni jalb qilish kuchaytirilishi kerak.', '["Real hayotdagi misollar yordamida nazariya mustahkamlandi.","Misollar amaliy va o''quvchilarga tushunarli.","O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan."]', '["Murakkab atamalar uchun qisqacha takror berib turish foydali.","Yozma misollarni daftar yoki taxta orqali ko''rsatish.","Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi."]', '["Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish.","Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi."]', '2026-03-21 06:11:00');
