INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1143, 70, 73, 68, 71, 'Asosiy mavzu yetkazildi, lekin tushuntirishda ba''zi joylar tezroq o''tib ketdi.', '["Misollar amaliy va o''quvchilarga tushunarli.","Ovoz baland va aniq, jaranglashi yaxshi."]', '["Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish.","Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi."]', '["Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi.","Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin."]', '2026-04-19 07:48:00');
