INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1157, 77, 83, 77, 85, 'Asosiy mavzu yetkazildi, lekin tushuntirishda ba''zi joylar tezroq o''tib ketdi.', '["Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi.","Ovoz baland va aniq, jaranglashi yaxshi.","Vizual yoki yozma misollar kontsentratsiyaga yordam berdi."]', '["Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish.","Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi."]', '["Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi.","Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi."]', '2026-04-12 09:03:00');
