INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1158, 90, 84, 90, 85, 'Pedagogik jihatdan kuchli dars. Kichik takomillashtirishlar bilan a''lo bo''lishi mumkin.', '["Real hayotdagi misollar yordamida nazariya mustahkamlandi.","Mavzu aniq va izchil yoritildi."]', '["Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish.","O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak."]', '["Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi.","Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi."]', '2026-04-16 08:55:00');
