INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1159, 70, 66, 72, 77, 'Asosiy mavzu yetkazildi, lekin tushuntirishda ba''zi joylar tezroq o''tib ketdi.', '["O''qituvchi savollarga aniq javob berdi.","Ovoz baland va aniq, jaranglashi yaxshi."]', '["O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak.","Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","Murakkab atamalar uchun qisqacha takror berib turish foydali."]', '["Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi.","Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi."]', '2026-03-25 06:22:00');
