INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1160, 64, 67, 70, 64, 'Asosiy mavzu yetkazildi, lekin tushuntirishda ba''zi joylar tezroq o''tib ketdi.', '["Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi.","O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan.","Misollar amaliy va o''quvchilarga tushunarli."]', '["Murakkab atamalar uchun qisqacha takror berib turish foydali.","Yozma misollarni daftar yoki taxta orqali ko''rsatish."]', '["Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish.","Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi.","Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi."]', '2026-04-14 03:38:00');
