INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1191, 1006, 'DI-301', 'OT — Amaliy mashq', 'Operatsion tizimlar', 4086, 'Operatsion tizim — bu kompyuter resurslarini boshqaruvchi va dasturlarga muhit yaratuvchi dastur. Asosiy funksiyalari: jarayonlarni boshqarish, xotira boshqaruvi, fayl tizimi, qurilmalar bilan ishlash.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1191, 83, 76, 80, 79, 'Pedagogik jihatdan kuchli dars. Kichik takomillashtirishlar bilan a''lo bo''lishi mumkin.', '["O''qituvchi savollarga aniq javob berdi.","Misollar amaliy va o''quvchilarga tushunarli.","Ovoz baland va aniq, jaranglashi yaxshi."]', '["Murakkab atamalar uchun qisqacha takror berib turish foydali.","Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak.","Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi."]', '["Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi.","Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi."]', '2026-03-08 03:50:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1192, 1006, 'DI-301', 'OT — Asosiy tushunchalar', 'Operatsion tizimlar', 4461, 'Operatsion tizim — bu kompyuter resurslarini boshqaruvchi va dasturlarga muhit yaratuvchi dastur. Asosiy funksiyalari: jarayonlarni boshqarish, xotira boshqaruvi, fayl tizimi, qurilmalar bilan ishlash.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1192, 81, 85, 76, 83, 'Dars yaxshi tashkil etilgan, mavzu chuqur va aniq yoritilgan. O''quvchilar bilan muloqot mustahkam.', '["Vizual yoki yozma misollar kontsentratsiyaga yordam berdi.","Mavzu aniq va izchil yoritildi."]', '["O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak.","Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi."]', '["Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi.","Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin."]', '2026-03-12 09:35:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1193, 1006, 'DI-301', 'OT — Misollar va tahlil', 'Operatsion tizimlar', 1956, 'Operatsion tizim — bu kompyuter resurslarini boshqaruvchi va dasturlarga muhit yaratuvchi dastur. Asosiy funksiyalari: jarayonlarni boshqarish, xotira boshqaruvi, fayl tizimi, qurilmalar bilan ishlash.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1193, 68, 69, 57, 76, 'O''rtacha sifatdagi dars — mavzu qamrab olindi, lekin o''quvchilar reaktsiyasiga ko''p e''tibor berilmadi.', '["Ovoz baland va aniq, jaranglashi yaxshi.","Real hayotdagi misollar yordamida nazariya mustahkamlandi."]', '["Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi.","Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi."]', '["Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi.","Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin.","Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi."]', '2026-04-14 04:30:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1194, 1007, 'RI-101', 'DM — Loyiha taqdimoti', 'Diskret matematika', 1770, 'Bugungi mavzu — to''plamlar va ulardagi amallar. To''plam — bu aniq belgilangan obyektlar yig''indisi. A = {1, 2, 3} kabi yoziladi. Element to''plamga tegishli yoki tegishli emas.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1194, 81, 75, 82, 80, 'Dars yaxshi tashkil etilgan, mavzu chuqur va aniq yoritilgan. O''quvchilar bilan muloqot mustahkam.', '["Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi.","Ovoz baland va aniq, jaranglashi yaxshi."]', '["Yozma misollarni daftar yoki taxta orqali ko''rsatish.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish."]', '["Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi.","Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi."]', '2026-04-09 06:14:00');
