INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1207, 88, 82, 77, 83, 'Mazmun va shaklning yaxshi muvozanati. Misollar mavzuni qo''llab-quvvatlaydi.', '["Real hayotdagi misollar yordamida nazariya mustahkamlandi.","Vizual yoki yozma misollar kontsentratsiyaga yordam berdi."]', '["Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish."]', '["Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish.","Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi."]', '2026-04-12 03:52:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1208, 1009, 'DI-201', 'LB — Yechimlar muhokamasi', 'Loyihalarni boshqarish', 4212, 'Agile metodologiyasi — bu loyihalarni iterativ tarzda boshqarish yondashuvi. Asoschi 2001-yilda 17 dasturchi yozgan Agile Manifesto.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1208, 75, 72, 70, 79, 'O''rtacha sifatdagi dars — mavzu qamrab olindi, lekin o''quvchilar reaktsiyasiga ko''p e''tibor berilmadi.', '["Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi.","Real hayotdagi misollar yordamida nazariya mustahkamlandi.","Mavzu aniq va izchil yoritildi."]', '["O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish."]', '["Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi.","Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi.","Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish."]', '2026-03-23 08:07:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1209, 1009, 'DI-201', 'LB — Misollar va tahlil', 'Loyihalarni boshqarish', 3520, 'Agile metodologiyasi — bu loyihalarni iterativ tarzda boshqarish yondashuvi. Asoschi 2001-yilda 17 dasturchi yozgan Agile Manifesto.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1209, 62, 58, 56, 68, 'Asosiy mavzu yetkazildi, lekin tushuntirishda ba''zi joylar tezroq o''tib ketdi.', '["Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi.","O''qituvchi savollarga aniq javob berdi."]', '["O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak.","Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak.","Ko''proq amaliy mashqlar berilsa yaxshi bo''lardi."]', '["Tinglovchilarga 5-7 daqiqada bir savol berish — diqqatni saqlaydi.","Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi.","Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi."]', '2026-04-17 07:08:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1210, 1009, 'DI-201', 'LB — Test va o''zlashtirish', 'Loyihalarni boshqarish', 2011, 'Agile metodologiyasi — bu loyihalarni iterativ tarzda boshqarish yondashuvi. Asoschi 2001-yilda 17 dasturchi yozgan Agile Manifesto.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1210, 64, 70, 67, 67, 'O''rtacha sifatdagi dars — mavzu qamrab olindi, lekin o''quvchilar reaktsiyasiga ko''p e''tibor berilmadi.', '["O''quvchilar bilan o''zaro muloqot yaxshi tashkil etilgan.","Tushunchalar bosqichma-bosqich oddiydan murakkabga qarab tushuntirildi.","Real hayotdagi misollar yordamida nazariya mustahkamlandi."]', '["Tushuntirish boshlanishida darsning maqsadi aniq aytilishi kerak.","Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi."]', '["Real loyiha yoki amaliy vazifa qo''shish — motivatsiyani oshiradi.","Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin."]', '2026-04-09 11:49:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1211, 1009, 'DI-201', 'LB — Misollar va tahlil', 'Loyihalarni boshqarish', 2545, 'Agile metodologiyasi — bu loyihalarni iterativ tarzda boshqarish yondashuvi. Asoschi 2001-yilda 17 dasturchi yozgan Agile Manifesto.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1211, 71, 67, 68, 80, 'Dars umumiy ma''noda yaxshi olib borildi, lekin amaliy qism va o''quvchilarni jalb qilish kuchaytirilishi kerak.', '["Real hayotdagi misollar yordamida nazariya mustahkamlandi.","O''qituvchi savollarga aniq javob berdi.","Mavzu aniq va izchil yoritildi."]', '["Yozma misollarni daftar yoki taxta orqali ko''rsatish.","O''quvchilarga savollar berib qatnashtirish keng bo''lishi kerak.","Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi."]', '["Har dars boshida 1-2 daqiqa o''tgan darsni qaytarish — yaxshi natija beradi.","Muhim atamalarni taxtaga yozib qo''yish — eslab qolishni osonlashtiradi.","Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin."]', '2026-03-12 12:22:00');
INSERT INTO lessons (id, user_id, group_name, topic, course_type, duration_seconds, transcript, created_at) VALUES (1212, 1009, 'DI-201', 'LB — Test va o''zlashtirish', 'Loyihalarni boshqarish', 2287, 'Agile metodologiyasi — bu loyihalarni iterativ tarzda boshqarish yondashuvi. Asoschi 2001-yilda 17 dasturchi yozgan Agile Manifesto.
INSERT INTO evaluations (lesson_id, overall_score, clarity_score, engagement_score, content_score, summary, strengths, improvements, advice, created_at) VALUES (1212, 88, 86, 76, 97, 'Dars yaxshi tashkil etilgan, mavzu chuqur va aniq yoritilgan. O''quvchilar bilan muloqot mustahkam.', '["Real hayotdagi misollar yordamida nazariya mustahkamlandi.","Misollar amaliy va o''quvchilarga tushunarli."]', '["Tezlikni biroz pasaytirish — ayrim joylar tez o''tib ketdi.","Dars oxirida qisqa xulosa va kalit fikrlarni qaytarish.","Murakkab atamalar uchun qisqacha takror berib turish foydali."]', '["Uy vazifasi sifatida 2-3 ta savol berish va keyingi darsda ko''rib chiqish.","Darsda Q&A vaqti aniq belgilash — talabalar savol berishdan tortinmasin.","Eng oddiy misoldan boshlab keyingi qadamga o''tish — barcha o''quvchilar bilan bir tezlikda yurishga yordam beradi."]', '2026-03-26 07:59:00');
