INSERT INTO lesson_tests (lesson_id, questions, key_terms, created_at) VALUES (1001, '[{"q":"Linear regressiya qanday muammoni hal qiladi?","choices":["Klassifikatsiya","Regressiya","Klasterizatsiya","Reduktsiya"],"correct_choice":1},{"q":"MSE nimani anglatadi?","choices":["Mean Squared Error","Multi Sample Estimator","Median Score Evaluation","Maximum Standard Error"],"correct_choice":0},{"q":"Gradient descent nima qiladi?","choices":["Ma''lumot yig''adi","Loss ni minimallashtiradi","Modelni saqlaydi","Vizualizatsiya qiladi"],"correct_choice":1}]', '[{"term":"Loss funksiyasi","explanation":"Modelning bashorati va haqiqiy qiymatlari orasidagi xatoni o''lchaydi."},{"term":"Gradient descent","explanation":"Loss funksiyasini iterativ ravishda minimallashtirish algoritmi."},{"term":"Overfitting","explanation":"Modelning o''qitish ma''lumotini juda yaxshi yodlab, yangi ma''lumotda yomon ishlashi."}]', '2026-04-23 09:39:00');
