INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1004, 1148, 'user', 'Overfitting nima?', '2026-04-24 14:55:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1004, 1148, 'assistant', 'Model o''qitish ma''lumotini juda yaxshi yodlab, yangi (ko''rilmagan) ma''lumotda yomon ishlashi. Yechimlar: ko''proq ma''lumot, modelni soddalashtirish, regularizatsiya, cross-validation.', '2026-04-24 14:55:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1010, 1149, 'user', 'Nega ba''zan davlat narxlarni belgilaydi?', '2026-03-18 14:18:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1010, 1149, 'assistant', 'Asosan ijtimoiy maqsadlar uchun: kambag''allarga oziq-ovqat narxini past tutish, ish haqi pastligini oldini olish (minimum ish haqi). Lekin bu ko''pincha tanqislikka yoki qora bozorga olib kelishi mumkin.', '2026-03-18 14:18:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1015, 1149, 'user', 'Nega ba''zan davlat narxlarni belgilaydi?', '2026-03-22 10:10:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1015, 1149, 'assistant', 'Asosan ijtimoiy maqsadlar uchun: kambag''allarga oziq-ovqat narxini past tutish, ish haqi pastligini oldini olish (minimum ish haqi). Lekin bu ko''pincha tanqislikka yoki qora bozorga olib kelishi mumkin.', '2026-03-22 10:10:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1017, 1113, 'user', 'Qachon stack ishlatilsa yaxshi?', '2026-03-26 17:01:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1017, 1113, 'assistant', 'Oxirgi qo''shilgan elementga birinchi murojaat qilish kerak bo''lganda. Klassik misol: brauzerda ''back'' tugmasi, undo funksiyasi, qavslarni tekshirish, va rekursiyani simulyatsiya qilish.', '2026-03-26 17:01:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1017, 1137, 'user', 'Nega O(n²) yomon?', '2026-03-27 10:39:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1017, 1137, 'assistant', 'Kirish hajmi 10 marta oshsa, vaqt 100 marta oshadi. 1000 ta element 1 soniyada bajarilsa, 10000 ta element 100 soniya oladi. Shuning uchun katta ma''lumotda O(n log n) yoki O(n) algoritmlar kerak.', '2026-03-27 10:39:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1018, 1125, 'user', 'Qachon stack ishlatilsa yaxshi?', '2026-03-22 12:35:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1018, 1125, 'assistant', 'Oxirgi qo''shilgan elementga birinchi murojaat qilish kerak bo''lganda. Klassik misol: brauzerda ''back'' tugmasi, undo funksiyasi, qavslarni tekshirish, va rekursiyani simulyatsiya qilish.', '2026-03-22 12:35:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1025, 1114, 'user', 'Scrum va Kanban orasidagi farq?', '2026-04-29 13:30:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1025, 1114, 'assistant', 'Scrum — sprintlar va aniq rollar bilan tuzilgan; har sprint oxirida release. Kanban — uzluksiz oqim, work-in-progress chegarasi bilan; istalgan vaqt release qilinadi. Kichik jamoalarda Kanban moslashuvchanroq.', '2026-04-29 13:30:00');
