INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1040, 1140, 'user', 'Qachon stack ishlatilsa yaxshi?', '2026-03-19 16:43:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1040, 1140, 'assistant', 'Oxirgi qo''shilgan elementga birinchi murojaat qilish kerak bo''lganda. Klassik misol: brauzerda ''back'' tugmasi, undo funksiyasi, qavslarni tekshirish, va rekursiyani simulyatsiya qilish.', '2026-03-19 16:43:00');
