INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1044, 1104, 'user', 'Nega O(n²) yomon?', '2026-04-16 12:31:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1044, 1104, 'assistant', 'Kirish hajmi 10 marta oshsa, vaqt 100 marta oshadi. 1000 ta element 1 soniyada bajarilsa, 10000 ta element 100 soniya oladi. Shuning uchun katta ma''lumotda O(n log n) yoki O(n) algoritmlar kerak.', '2026-04-16 12:31:00');
