INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1047, 1116, 'user', 'REST API nima?', '2026-03-02 12:11:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1047, 1116, 'assistant', 'REST — bu HTTP metodlari (GET, POST, PUT, DELETE) yordamida resurslarni boshqaruvchi arxitektura uslubi. Har bir resurs URL ga ega va metodlar uning ustida amal bajaradi: GET /users — ro''yxat olish, POST /users — yangi yaratish.', '2026-03-02 12:11:00');
