INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1106, 1110, 'user', 'Process va thread orasidagi farq?', '2026-04-08 16:26:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1106, 1110, 'assistant', 'Process — mustaqil dastur, o''z manzillar makoniga ega. Thread — process ichidagi yengilroq birlik, xotirani process bilan bo''lishadi. Threadlar bir-biri bilan tezroq aloqa qiladi, lekin sinxronizatsiya muammolari bor.', '2026-04-08 16:26:00');
