INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1110, 1110, 'user', 'ChatGPT qanday ishlaydi?', '2026-03-03 16:24:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1110, 1110, 'assistant', 'ChatGPT — bu katta til modeli (LLM) bo''lib, milliardlab matnlarda o''qitilgan. U keyingi so''zni bashorat qilish orqali javob yaratadi. Ya''ni ''tushunish'' emas, statistik naqshlarga asoslangan.', '2026-03-03 16:24:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1110, 1122, 'user', 'AI ish o''rnimni egallaydimi?', '2026-03-04 10:00:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1110, 1122, 'assistant', 'Aniq vazifalarni avtomatlashtiradi, lekin ko''p kasblarda — ayniqsa ijodiy, mas''uliyatli yoki murakkab muloqot talab qiladigan — odam kerak qoladi. Eng yaxshi strategiya: AI ni vosita sifatida o''rganish.', '2026-03-04 10:00:00');
