INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1152, 1142, 'user', 'REST API nima?', '2026-04-29 10:53:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1152, 1142, 'assistant', 'REST — bu HTTP metodlari (GET, POST, PUT, DELETE) yordamida resurslarni boshqaruvchi arxitektura uslubi. Har bir resurs URL ga ega va metodlar uning ustida amal bajaradi: GET /users — ro''yxat olish, POST /users — yangi yaratish.', '2026-04-29 10:53:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1154, 1142, 'user', 'useEffect qachon ishga tushadi?', '2026-04-17 13:15:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1154, 1142, 'assistant', 'Default holatda har render dan keyin. Dependency array berilsa, faqat shu qiymatlar o''zgarganda. Bo''sh array [] berilsa — faqat birinchi render dan keyin (componentDidMount kabi).', '2026-04-17 13:15:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1155, 1130, 'user', 'REST API nima?', '2026-03-06 13:05:00');
