INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1186, 1123, 'user', 'Process va thread orasidagi farq?', '2026-03-23 15:38:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1186, 1123, 'assistant', 'Process — mustaqil dastur, o''z manzillar makoniga ega. Thread — process ichidagi yengilroq birlik, xotirani process bilan bo''lishadi. Threadlar bir-biri bilan tezroq aloqa qiladi, lekin sinxronizatsiya muammolari bor.', '2026-03-23 15:38:00');
