INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1194, 1146, 'user', 'Kuchli to''plamda nima uchun 2^n element bo''ladi?', '2026-04-13 13:59:00');
INSERT INTO mentor_chats (lesson_id, student_id, role, content, created_at) VALUES (1194, 1146, 'assistant', 'Har bir element qism to''plamda yoki bor, yoki yo''q (2 variant). N ta element bo''lsa, 2 × 2 × ... × 2 (n marta) = 2^n ta turli kombinatsiya bo''ladi.', '2026-04-13 13:59:00');
